-- [Claude | 2026-10-16 | CLAUDE-MG | LAB DGB - FOTOGRAFIAS CATALOGO GENERAL MAPA POR ESTADOS V001]
-- INT-10. Catalogo General de Fotografias: mapa de la Republica por estados.
--   1) Concede al rol canonico DIRECTOR_GENERAL (por codigo) la lectura/visibilidad del
--      Catalogo General (permisos FOTOGRAFIAS_CATALOGO_GENERAL_*, todos de lectura).
--   2) Datos FICTICIOS: proyectos de Instalaciones en estados reales y sus fotografias
--      (ilustraciones SVG embebidas, sin enlaces externos) para ver el mapa en el LAB.
-- Reutiliza tablas existentes (ins_fl, ins_proyecto_fotos). Idempotente.

INSERT INTO `rol_permisos` (id_rol,id_subelemento_accion,permitido,created_at,updated_at)
SELECT r.id_rol,a.id_subelemento_accion,1,'2026-10-16 00:00:00','2026-10-16 00:00:00'
FROM `roles` r JOIN `perm_subelemento_acciones` a ON a.codigo_permiso LIKE 'FOTOGRAFIAS_CATALOGO_GENERAL_%'
WHERE r.codigo='DIRECTOR_GENERAL'
  AND NOT EXISTS (SELECT 1 FROM `rol_permisos` rp WHERE rp.id_rol=r.id_rol AND rp.id_subelemento_accion=a.id_subelemento_accion);
UPDATE `rol_permisos` SET permitido=1,updated_at='2026-10-16 00:00:00'
WHERE permitido<>1
  AND id_rol IN (SELECT id_rol FROM `roles` WHERE codigo='DIRECTOR_GENERAL')
  AND id_subelemento_accion IN (SELECT id_subelemento_accion FROM `perm_subelemento_acciones` WHERE codigo_permiso LIKE 'FOTOGRAFIAS_CATALOGO_GENERAL_%');

